    if (C.card) { C.card.tex.dispose(); C.card.matTex.dispose(); }
    if (!C.coin.visible) { C.coin.position.copy(t.card).add(V3(0.04, 0.02, 0)); }
    const sc = createScratch(full, { onReveal: () => snd.reveal(), onDone: (res) => finishCard(card, res) }); const tex = new THREE.CanvasTexture(sc.canvas); tex.colorSpace = THREE.SRGBColorSpace; tex.anisotropy = 8; const matTex = new THREE.CanvasTexture(sc.mat); matTex.anisotropy = 4;
