  function tableButtons() { const c = C.card; const kind = c ? c.full.kind : 'fixed'; const can = c && !c.sc.st.done && (kind === 'ladder' || kind === 'mines') && c.sc.st.k >= 1 && !c.sc.st.fell; $('caTCash').classList.toggle('hidden', !(c && (kind === 'ladder' || kind === 'mines'))); $('caTCash').disabled = !can; $('caTCash').textContent = can ? `Kasse machen: ${euro(cardWin(c.full, c.sc.st.k), true)}` : 'Kasse machen'; $('caTAuto').textContent = kind === 'fixed' ? 'Alles aufrubbeln (R)' : kind === 'pick' ? 'Felder wählen lassen (R)' : 'Nächstes Feld (R)'; const more = cardsSrc().filter((q) => q.st !== 'fertig' && (!c || q.uid !== c.inv.uid)).length; $('caTNext').disabled = !more; $('caTNext').textContent = `Nächstes Los (N)${more ? ' · noch ' + more : ''}`; }
  function tableList() { const box = $('caTList'); box.textContent = ''; for (const q of cardsSrc().filter((x) => x.st !== 'fertig').slice(0, 14)) { const b = document.createElement('button'); b.type = 'button'; b.className = 'ca-tli' + (C.card && q.uid === C.card.inv.uid ? ' on' : ''); const img = document.createElement('img'); img.src = cardThumb(q.cid, 320).url; img.alt = ''; b.title = CARD[q.cid].name; b.append(img); b.onclick = () => { if (C.card && !C.card.sc.st.done && C.card.sc.progress() > 0.02 && q.uid !== C.card.inv.uid) { toast('Rubbel erst dieses Los fertig.'); return; } loadCard(q.uid); }; box.append(b); } }
  const hit = new THREE.Vector3(); const ndc = new THREE.Vector2();
  function cardUV(cx, cy) { ndc.set(cx / window.innerWidth * 2 - 1, -(cy / window.innerHeight) * 2 + 1); C.ray.setFromCamera(ndc, C.cam); const h = C.ray.intersectObject(C.cardMesh, false)[0]; if (!h) { const pl = new THREE.Plane(V3(0, 1, 0), -C.cardMesh.position.y); if (C.ray.ray.intersectPlane(pl, hit)) return { p: hit.clone(), uv: null }; return null; } return { p: h.point.clone(), uv: h.uv }; }
  function scratchAt(e) { if (!C.card || C.card.sc.st.done) return; const r = cardUV(e.clientX, e.clientY); if (!r || !r.uv) { C.last = null; return; } const x = r.uv.x * CW; const y = (1 - r.uv.y) * CH; const L = C.last || { x, y }; const n = C.card.sc.scratchLine(L.x, L.y, x, y, 24); const sp = Math.hypot(x - L.x, y - L.y); if (n > 0) snd.scratch(sp / 26); C.last = { x, y }; tableButtons(); }
  function autoScratch() { const c = C.card; if (!c || c.sc.st.done || C.autoQ) return; const k = c.sc.nextField(); if (k < 0) return; const f = c.sc.center(k); const pts = []; const rows = Math.max(2, Math.ceil(f.h / 22)); for (let j = 0; j <= rows; j++) { const y = f.y - f.h / 2 + 6 + j * (f.h - 12) / rows; pts.push([j % 2 ? f.x + f.w / 2 - 8 : f.x - f.w / 2 + 8, y], [j % 2 ? f.x - f.w / 2 + 8 : f.x + f.w / 2 - 8, y]); } C.autoQ = { pts, i: 0, u: 0, field: k, all: c.full.kind === 'fixed' }; }
  function autoStep(dt) { const q = C.autoQ; const c = C.card; if (!q || !c) return; if (c.sc.st.done) { C.autoQ = null; return; } const speed = 1400; let left = speed * dt; while (left > 0 && q.i < q.pts.length - 1) { const a = q.pts[q.i]; const b = q.pts[q.i + 1]; const seg = Math.hypot(b[0] - a[0], b[1] - a[1]); const step = Math.min(left, seg * (1 - q.u)); const u2 = q.u + step / Math.max(seg, 1); const x0 = a[0] + (b[0] - a[0]) * q.u; const y0 = a[1] + (b[1] - a[1]) * q.u; const x1 = a[0] + (b[0] - a[0]) * u2; const y1 = a[1] + (b[1] - a[1]) * u2; c.sc.scratchLine(x0, y0, x1, y1, 26); snd.scratch(1.2); C.autoPos = [x1, y1]; q.u = u2; left -= step; if (q.u >= 0.999) { q.i++; q.u = 0; } }
    if (q.i >= q.pts.length - 1) { c.sc.endStroke(); C.autoQ = null; tableButtons(); if (q.all && !c.sc.st.done) autoScratch(); else if (c.full.kind === 'pick' && !c.sc.st.done) autoScratch(); } }
  function cashOut() { const c = C.card; if (!c || c.sc.st.done) return; if (c.sc.cashOut()) snd.click(); }
  function nextCard() { if (C.card && !C.card.sc.st.done && C.card.sc.progress() > 0.02) { toast('Rubbel erst dieses Los fertig.'); return; } const L = cardsSrc().filter((q) => q.st !== 'fertig' && (!C.card || q.uid !== C.card.inv.uid)); if (!L.length) { toast(C.duel ? 'Alle drei Duell-Lose sind gerubbelt.' : 'Keine weiteren Lose. Am Stand gibt es Nachschub.'); return; } loadCard(L[0].uid); }
