    const c = C.card; if (!c || c.done) return; c.done = true; const dbl = C.duel ? 1 : doubleNow(C.S) * SCOIN[c.coin || 'kupfer'].money; const win = Math.round(res.win * dbl); const tier = win <= 0 ? 0 : win >= CARD[card.cid].price * 50 ? 3 : win >= CARD[card.cid].price * 5 ? 2 : 1;
    setTimeout(() => { if (tier) { snd.win(tier); bigWin(C.duel ? 'Duell-Los' : dbl > 1 ? 'Doppelter Gewinn!' : tier >= 3 ? 'JACKPOT!' : tier === 2 ? 'Großer Gewinn!' : 'Gewonnen!', euro(win, true), tier >= 3 ? 'jackpot' : tier === 2 ? 'big' : 'small'); burst(c.full && C.cardMesh.position, tier * 14 + 6); C.cheerT = tier >= 2 ? 2.4 : 1.4; } else { snd.lose(); bigWin(res.fell ? 'Pech gehabt' : 'Leider nichts', 'Nächstes Mal!', 'none'); } }, 350);
