  function standUp() { C.phase = 'play'; C.table = -1; C.duel = false; $('caTable').classList.add('hidden'); $('caCross').classList.remove('hidden'); hud.classList.remove('ca-at-table'); canvas.style.cursor = ''; C.cardMesh.visible = false; C.coin.visible = false; C.pile.forEach((m) => { m.visible = false; }); const me = C.myFig(); me.setVisible(false); me.fig.setOwn(false); if (C.card && C.card.done) { /* fertig */ } C.card = null; C.autoQ = null; hint('Klick ins Bild, um die Maus wieder zu nutzen.'); }
  function tableCam(dt) { const t = C.W.tables[C.table]; const z = C.zoom || 0; const pos = V3(t.card.x + 0.4 - z * 0.5, 1.16 - z * 0.42, t.card.z); const look = V3(t.card.x - 0.015, 0.8, t.card.z); const cam = C.cam; const q0 = new THREE.Quaternion(); const m4 = new THREE.Matrix4().lookAt(pos, look, V3(0, 1, 0)); q0.setFromRotationMatrix(m4); const from = C.camFrom; if (from && from.t < 1) { from.t = Math.min(1, from.t + dt / 0.6); const k = from.t * from.t * (3 - 2 * from.t); cam.position.lerpVectors(from.p, pos, k); cam.quaternion.slerpQuaternions(from.q, q0, k); } else { cam.position.copy(pos); cam.quaternion.copy(q0); } cam.fov = 42; }

  // ---------------- Münzregen ----------------
