    { const b = C.staff.bar; const near = m.x < -11 && m.z > -22 && m.z < -10; const tz = near ? clamp(m.z, -21, -11) : -16 + Math.sin(t * 0.15) * 4; if (Math.abs(tz - b.z) > 0.15) { walkTo(b, -15.45, tz, dt, 0.9); } else { b.mode = 'stand'; b.yaw = Math.PI / 2; b.act = near ? 'counter' : 'wipe'; } b.lookAt = near ? V3(m.x, EYE, m.z) : null; }
