    if (C.W) { enter(); return; } C.loading = true; C.queue = []; hud.classList.remove('hidden'); G.mode = 'casino'; showScreen(null); $('hud').classList.add('hidden'); showLoad(true, 'Teo’s Casino öffnet die Türen …'); await nextPaint(); const lt = [performance.now()];
    build(); lt.push(performance.now()); showLoad(true, 'Die Lichter gehen an …'); await nextPaint();
    try { const rt = new THREE.WebGLRenderTarget(64, 64, { type: THREE.HalfFloatType }); const prev = renderer.getRenderTarget(); renderer.setRenderTarget(rt); C.cam.position.set(0, 1.6, 2); C.cam.lookAt(0, 1.6, -10); C.cam.updateMatrixWorld(); lt.push(performance.now()); await renderer.compileAsync(C.W.scene, C.cam); lt.push(performance.now()); const I = C.intro && C.intro.I; if (I && I.home) await renderer.compileAsync(I.home.scene, C.cam); lt.push(performance.now()); if (I && I.ride) await renderer.compileAsync(I.ride.scene, C.cam); lt.push(performance.now()); C.loadT = lt.slice(1).map((t, i) => Math.round(t - lt[i])); renderer.setRenderTarget(prev); rt.dispose(); } catch (e) { /* ohne Vorab-Übersetzung geht es auch, nur langsamer */ }
