  function back() { if (C.net) { stop(); endSession(); return; } stop(); showScreen('gallery'); }
  function stop() { if (!C.on) return; if (C.intro && C.intro.I.on) C.intro.finish(true); C.on = false; save(); unlock(); hud.classList.add('hidden'); closeUI(); $('caTable').classList.add('hidden'); canvas.style.cursor = ''; snd.music(null, 1); snd.amb(0); snd.story(false); snd.rain(0); snd.bus(0); snd.neon(false); snd.home(0); if (C.day) C.day.stop(); if (C.slots2) C.slots2.stop(); if (C.tables3) C.tables3.stop(); if (C.arc5) C.arc5.stop(); C.duel = false; C.phase = 'off'; for (const [id] of C.remotes) playerLeft(id); C.net = null; C.host = true; if (C.card) { C.cardMesh.visible = false; C.coin.visible = false; C.card = null; } if (G.mode === 'casino') G.mode = 'menu'; tour.open = false; tour.el.classList.add('hidden'); }
  $('caResume').onclick = () => togglePause(false); $('caIntroAgain').onclick = () => { closeUI(); if (C.phase === 'home' || C.phase === 'cut') { toast('Das Intro lässt sich im Casino noch einmal ansehen.'); return; } if (C.phase === 'table') standUp(); startIntro(); }; $('caHelp').onclick = () => { closeUI(); tour.show(); }; $('caQuit').onclick = () => openUI('exit');
  $('caExitNo').onclick = closeUI; $('caExitYes').onclick = () => { closeUI(); back(); }; $('caTAuto').onclick = autoScratch; $('caTCash').onclick = cashOut; $('caTNext').onclick = nextCard; $('caTUp').onclick = standUp; $('caInvBtn').onclick = () => openUI('inv'); $('caSkipBtn').onclick = () => { if (C.phase === 'intro' && !C.introLock) C.intro.finish(true); };
