    if (C.phase === 'slot') C.slots2.frame(real); if (C.phase === 'game') C.tables3.frame(real); if (C.phase === 'arc') C.arc5.frame(real);
    // Rückfallnetz: jeder Weg, der das Level hebt, ohne selbst den Aufstieg zu zeigen (Münzkauf, Aufgaben-Belohnung, Fundmünze …). Wege mit eigener Inszenierung (Los, Automat, Bruno) melden sich vorher.
