    if (C.net && C.host && C.S && (C.castT = (C.castT || 0) + real) > 15) { C.castT = 0; if (C.net.count() > 1) pushState(); } // Sicherheitsnetz: der Host schickt den Stand alle 15 s erneut, falls einmal etwas verloren ging
    // Mehrspieler-Leiste
